package provision

import (
	"bytes"
	"fmt"
	"regexp"
	"text/template"
)

// UserDataParams fill the cloud-init script that installs and enrols a runner.
type UserDataParams struct {
	EnrollURL string            // http://<controller-private-ip>:4223
	Token     string            // one-time enrolment token
	SHA256    map[string]string // uname -m -> sha256 of that runner binary
}

var userDataTmpl = template.Must(template.New("ud").Parse(`#!/bin/bash
# wrangl runner bootstrap (generated by the controller)
set -euo pipefail
ARCH=$(uname -m)
case "$ARCH" in
{{- range $arch, $sum := .SHA256}}
  {{$arch}}) SUM={{$sum}} ;;
{{- end}}
  *) echo "wrangl: unsupported arch $ARCH" >&2; exit 1 ;;
esac
for i in 1 2 3 4 5; do
  curl -fsS --retry 5 --retry-connrefused "{{.EnrollURL}}/dl/wrangl-linux-${ARCH}" -o /usr/local/bin/wrangl && break
  sleep $((i * 3))
done
echo "${SUM}  /usr/local/bin/wrangl" | sha256sum -c -
chmod 0755 /usr/local/bin/wrangl
# The runner clones and pushes with git.
command -v git >/dev/null || dnf install -y git || (apt-get update && apt-get install -y git)
exec /usr/local/bin/wrangl runner bootstrap --controller "{{.EnrollURL}}" --token "{{.Token}}"
`))

var (
	safeURL   = regexp.MustCompile(`^https?://[A-Za-z0-9.\-:\[\]]+$`)
	safeToken = regexp.MustCompile(`^[A-Za-z0-9_\-]+$`)
	safeSum   = regexp.MustCompile(`^[0-9a-f]{64}$`)
	safeArch  = regexp.MustCompile(`^[a-z0-9_]+$`)
)

// RenderUserData renders the bootstrap script. Inputs are validated strictly because
// they are interpolated into a root shell script.
func RenderUserData(p UserDataParams) (string, error) {
	if !safeURL.MatchString(p.EnrollURL) || !safeToken.MatchString(p.Token) || len(p.SHA256) == 0 {
		return "", fmt.Errorf("unsafe or missing user-data parameters")
	}
	for a, s := range p.SHA256 {
		if !safeArch.MatchString(a) || !safeSum.MatchString(s) {
			return "", fmt.Errorf("bad binary checksum entry %q=%q", a, s)
		}
	}
	var b bytes.Buffer
	if err := userDataTmpl.Execute(&b, p); err != nil {
		return "", err
	}
	if b.Len() > 16*1024 {
		return "", fmt.Errorf("user-data is %d bytes, over EC2's 16 KiB limit", b.Len())
	}
	return b.String(), nil
}
